<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Sorting Algorithm Visualizer</title>
<style>
  * { margin: 0; padding: 0; box-sizing: border-box; }
  body {
    background: #0d1117;
    color: #c9d1d9;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Helvetica, Arial, sans-serif;
    min-height: 100vh;
    display: flex;
    flex-direction: column;
    align-items: center;
    padding: 24px;
  }
  h1 { margin-bottom: 20px; color: #58a6ff; font-size: 1.6rem; }
  #controls { display: flex; gap: 12px; margin-bottom: 24px; }
  button {
    background: #21262d;
    color: #c9d1d9;
    border: 1px solid #30363d;
    padding: 10px 22px;
    border-radius: 6px;
    cursor: pointer;
    font-size: 14px;
    font-weight: 500;
    transition: background .15s, border-color .15s;
  }
  button:hover { background: #30363d; border-color: #58a6ff; }
  button:active { background: #1f6feb; }
  #bars {
    display: flex;
    align-items: flex-end;
    justify-content: center;
    width: 100%;
    max-width: 960px;
    height: 520px;
    background: #161b22;
    border: 1px solid #30363d;
    border-radius: 8px;
    padding: 24px 12px 12px;
    gap: 2px;
  }
  .bar {
    flex: 1;
    max-width: 32px;
    min-height: 2px;
    background: linear-gradient(to top, #1f6feb, #58a6ff);
    border-radius: 3px 3px 0 0;
    transition: height 0.08s ease;
  }
  #info {
    margin-top: 14px;
    color: #8b949e;
    font-size: 13px;
    height: 20px;
  }
</style>
</head>
<body>

<h1>Sorting Visualizer</h1>
<div id="controls">
  <button id="sort">▶ Sort</button>
  <button id="shuffle">🔀 Shuffle</button>
  <button id="reset">↻ Reset</button>
</div>
<div id="bars"></div>
<div id="info"></div>

<script>
(function () {
  "use strict";

  const SIZE = 60;
  let data = [];
  let sortState = null;
  let isSorting = false;
  let animTimer = null;

  /* ---- helpers ---- */

  function randInt(min, max) {
    return Math.floor(Math.random() * (max - min + 1)) + min;
  }

  function fillRandom() {
    data = [];
    for (let i = 0; i < SIZE; i++) data.push(randInt(5, 95));
  }

  function stopAnim() {
    isSorting = false;
    if (animTimer) { clearTimeout(animTimer); animTimer = null; }
  }

  /* ---- rendering ---- */

  function draw() {
    const container = document.getElementById("bars");
    container.innerHTML = "";
    if (data.length === 0) return;
    const max = Math.max(...data, 1);
    for (let i = 0; i < data.length; i++) {
      const bar = document.createElement("div");
      bar.className = "bar";
      bar.style.height = Math.max(2, (data[i] / max) * 100) + "%";
      container.appendChild(bar);
    }
    const info = document.getElementById("info");
    if (sortState && !sortState.done) {
      info.textContent = "Sorting… pass " + (sortState.i + 1) + " of " + (data.length - 1);
    } else {
      info.textContent = window.viz.sorted() ? "Array is sorted" : "Ready";
    }
  }

  /* ---- API ---- */

  window.viz = {
    array: function () { return data; },

    setArray: function (a) {
      stopAnim();
      data = Array.isArray(a) ? a.slice() : [];
      sortState = null;
      draw();
    },

    sortStep: function () {
      const n = data.length;
      if (n <= 1) { sortState = null; return true; }

      if (!sortState) {
        sortState = { i: 0, j: 1, minIndex: 0 };
      }

      if (sortState.i >= n - 1) {
        sortState = null;
        draw();
        return true;
      }

      /* one comparison step (inner loop) */
      if (data[sortState.j] < data[sortState.minIndex]) {
        sortState.minIndex = sortState.j;
      }
      sortState.j++;

      /* inner loop finished → swap & advance outer loop */
      if (sortState.j >= n) {
        const tmp = data[sortState.i];
        data[sortState.i] = data[sortState.minIndex];
        data[sortState.minIndex] = tmp;

        sortState.i++;
        sortState.j = sortState.i + 1;
        sortState.minIndex = sortState.i;

        if (sortState.i >= n - 1) {
          sortState = null;
          draw();
          return true;
        }
      }

      draw();
      return false;
    },

    sorted: function () {
      for (let i = 1; i < data.length; i++) {
        if (data[i] < data[i - 1]) return false;
      }
      return true;
    }
  };

  /* ---- button wiring ---- */

  document.getElementById("sort").addEventListener("click", function () {
    if (isSorting) return;
    isSorting = true;

    function tick() {
      if (!isSorting) return;
      const done = window.viz.sortStep();
      if (done) { isSorting = false; draw(); return; }
      animTimer = setTimeout(tick, 35);
    }
    tick();
  });

  document.getElementById("shuffle").addEventListener("click", function () {
    stopAnim();
    const n = data.length;
    for (let i = n - 1; i > 0; i--) {
      const j = randInt(0, i);
      const tmp = data[i]; data[i] = data[j]; data[j] = tmp;
    }
    sortState = null;
    draw();
  });

  document.getElementById("reset").addEventListener("click", function () {
    stopAnim();
    fillRandom();
    sortState = null;
    draw();
  });

  /* ---- init ---- */
  fillRandom();
  draw();
})();
</script>
</body>
</html>
